                    console.log('[HaxBion glow] disco jugador en (' + x.toFixed(1) + ', ' + y.toFixed(1) + '), myPos=' + (myPos ? '(' + myPos.x.toFixed(1) + ', ' + myPos.y.toFixed(1) + ')' : 'null') + ', wantsGlow=' + wantsGlow);
